diff --git a/core/engine/worker.c b/core/engine/worker.c
index 3b50db93..aa111832 100644
--- a/core/engine/worker.c
+++ b/core/engine/worker.c
@@ -196,6 +196,7 @@ void bsal_worker_start(struct bsal_worker *worker, int processor)
     worker->last_report = time(NULL);
     worker->epoch_start_in_nanoseconds = bsal_timer_get_nanoseconds();
     worker->loop_start_in_nanoseconds = worker->epoch_start_in_nanoseconds;
+    worker->loop_end_in_nanoseconds = worker->loop_start_in_nanoseconds;
     worker->scheduling_epoch_start_in_nanoseconds = worker->epoch_start_in_nanoseconds;
 }

@@ -296,6 +297,13 @@ float bsal_worker_get_loop_load(struct bsal_worker *self)
     current_nanoseconds = self->loop_end_in_nanoseconds;
     elapsed_from_start = current_nanoseconds - self->loop_start_in_nanoseconds;

+    /* This code path is currently not implemented when using
+     * only 1 thread
+     */
+    if (elapsed_from_start == 0) {
+        return 0;
+    }
+
     loop_load = (0.0 + self->loop_used_nanoseconds) / elapsed_from_start;

     /* Avoid negative zeros

diff --git a/core/engine/worker_hot_code.c b/core/engine/worker_hot_code.c
index 63c3a9ba..3756e900 100644
--- a/core/engine/worker_hot_code.c
+++ b/core/engine/worker_hot_code.c
@@ -37,7 +37,7 @@ void bsal_worker_run(struct bsal_worker *worker)
     void *buffer;
 #endif

-#ifdef BSAL_NODE_ENABLE_LOAD_REPORTING
+#ifdef BSAL_NODE_ENABLE_INSTRUMENTATION
     clock_t current_time;
     clock_t elapsed;
     int period;
@@ -55,7 +55,7 @@ void bsal_worker_run(struct bsal_worker *worker)

     bsal_worker_lock(worker);

-#ifdef BSAL_NODE_ENABLE_LOAD_REPORTING
+#ifdef BSAL_NODE_ENABLE_INSTRUMENTATION
     period = BSAL_NODE_LOAD_PERIOD;
     current_time = time(NULL);

@@ -107,7 +107,7 @@ void bsal_worker_run(struct bsal_worker *worker)
         }
 #endif

-#ifdef BSAL_NODE_ENABLE_LOAD_REPORTING
+#ifdef BSAL_NODE_ENABLE_INSTRUMENTATION
         start_time = bsal_timer_get_nanoseconds();
 #endif

@@ -117,7 +117,7 @@ void bsal_worker_run(struct bsal_worker *worker)

         worker->busy = 0;

-#ifdef BSAL_NODE_ENABLE_LOAD_REPORTING
+#ifdef BSAL_NODE_ENABLE_INSTRUMENTATION
         end_time = bsal_timer_get_nanoseconds();

         elapsed_nanoseconds = end_time - start_time;

diff --git a/core/engine/worker_pool.c b/core/engine/worker_pool.c
index 4bf80bb7..b82e2e94 100644
--- a/core/engine/worker_pool.c
+++ b/core/engine/worker_pool.c
@@ -351,7 +351,9 @@ void bsal_worker_pool_print_efficiency(struct bsal_worker_pool *pool)
         efficiency += bsal_worker_get_loop_load(worker);
     }

-    efficiency /= pool->workers;
+    if (pool->workers != 0) {
+        efficiency /= pool->workers;
+    }

     printf("node %d efficiency: %.2f\n",
                     bsal_node_name(pool->node),
